export const I18N_LOCALIZE_ENTRIES = [...Object.entries(I18N_EN), ...Object.entries(I18N_DYNAMIC_EN)]
  .sort(([a], [b]) => b.length - a.length);
// 紧邻这些字符时说明命中的是路径/标识符的一部分,不是产品文案。
export const I18N_TOKEN_BOUNDARY = /[\\/._\-a-zA-Z0-9]/;

/// 只替换"独立出现"的产品文案。
/// 原实现对整段自由文本无边界 replaceAll,而该函数同时用于渲染用户输入、模型输出与
/// 文件路径,于是英文模式下 `crates/前端/模型.md` 被改写成 `crates/Frontend/Model.md`
/// ——展示层篡改用户数据(D-135)。现在命中处紧邻路径分隔符或 ASCII 标识符字符即跳过。
export function replaceStandalone(text, source, translated) {
  if (!source) return text;
  let out = "";
  let index = 0;
  for (;;) {
    const at = text.indexOf(source, index);
    if (at < 0) return out + text.slice(index);
    const before = at > 0 ? text[at - 1] : "";
    const after = text[at + source.length] ?? "";
    const inToken = I18N_TOKEN_BOUNDARY.test(before) || I18N_TOKEN_BOUNDARY.test(after);
    out += text.slice(index, at) + (inToken ? source : translated);
    index = at + source.length;
  }
}
export function localizeDynamic(value) {
  const text = String(value ?? "");
  if (!languageIsEnglish()) return text;
  // 整串命中优先:状态文案通常整句就是一个 key,这条路径最准也最快。
  const trimmed = text.trim();
  const whole = I18N_DYNAMIC_EN[trimmed] ?? I18N_EN[trimmed];
  if (whole) return text.replace(trimmed, whole);
  let out = text;
  for (const [source, translated] of I18N_LOCALIZE_ENTRIES) {
    out = replaceStandalone(out, source, translated);
  }
  return out;
}
export function languageIsEnglish() {
  return resolveUiLanguage() === "en";
}
export function t(key) {
  const language = resolveUiLanguage();
  return language === "en" ? (I18N_EN[key] || I18N_DYNAMIC_EN[key] || key) : key;
}
// 状态枚举 → 展示词(中英文都走 04-status-words.js 那一张表;中文界面不再显示 todo/doing/done 原文)。
// scope 只给同一枚举在别处另有含义时用(执行单元的 active),缺省按台账状态。
export function localizedStatusWord(status, scope = "") {
  return statusWord(status, languageIsEnglish(), scope);
}
export function localizedDocStatus(status) {
  return localizedStatusWord(status);
}
// 运行阶段(后端给的中文字面量)→ 当前界面语言的展示词(04-status-words.js 的 STAGE_WORDS_EN)。
export function localizedStage(stage) {
  return stageWord(stage, languageIsEnglish());
}
export function applyLanguage() {
  // R-140 批10:MutationObserver 退役。动态字符串(状态栏/日志/活动卡/权限队列等)全部
  // 在渲染点经 t()/localizeDynamic 产出;语言切换时由 change 处理器里的 syncDynamicUiLanguage/
  // reconcileTasksPanel/syncSidebar/renderProviders/refreshDocs/refreshWorktrees/
  // refreshConversationList 重渲染。这里只做两件事:同步 <html lang> 与一次性应用静态
  // data-i18n-*(初始化与切语言各一次),不再全文档扫描文本节点改写(禁止事后扫描,D-202)。
  const language = resolveUiLanguage();
  document.documentElement.lang = language === "en" ? "en" : "zh-CN";
  applyDataI18nKeys(document.body, language);
}
// R-140 批1/批2:data-i18n-key/data-i18n-title 渲染点翻译统一入口。
// 消息容器内的动态文案(复制按钮、错误级别)与静态 DOM(侧栏标题、按钮属性)共用:
// 元素渲染时写入 key,语言切换/节点插入时由这里重算 t()。这是「翻译发生在渲染点」
// 的落地,不依赖 observer 事后词典改写。
// data-i18n-zh:同字不同义时中文显示与 key 分开写。key 是中文原文,一字只能一译;「排队」已是状态词(Queued,
// 工作区卡片「排队 N 条」),输入区交付方式要的是动词 Queue——key 用带限定的「排队 queue」,中文仍显示 data-i18n-zh。
export function applyDataI18nKeys(root, language) {
  if (!root || typeof root.querySelectorAll !== "function") return;
  for (const el of root.querySelectorAll("[data-i18n-key]")) {
    const key = el.dataset.i18nKey;
    if (!key) continue;
    const next = language === "en" ? (I18N_EN[key] || I18N_DYNAMIC_EN[key] || key) : (el.dataset.i18nZh || key);
    if (el.textContent !== next) el.textContent = next;
  }
  for (const el of root.querySelectorAll("[data-i18n-title]")) {
    const key = el.dataset.i18nTitle;
    if (!key) continue;
    const next = language === "en" ? (I18N_EN[key] || I18N_DYNAMIC_EN[key] || key) : key;
    // R-140 批10:统一走 getAttribute/setAttribute(真实浏览器 IDL 反射会同步 title
    // property;冒烟假 DOM 的 setAttribute 同样补了 title/placeholder 反射)。
    if (el.getAttribute("title") !== next) el.setAttribute("title", next);
  }
  // R-140 批4/批10:aria-label/placeholder 与 title 同走渲染点(data-i18n-*)。
  // 属性不在此补齐会在英文态漏翻。
  for (const el of root.querySelectorAll("[data-i18n-aria-label]")) {
    const key = el.dataset.i18nAriaLabel;
    if (!key) continue;
    const next = language === "en" ? (I18N_EN[key] || I18N_DYNAMIC_EN[key] || key) : key;
    if (el.getAttribute("aria-label") !== next) el.setAttribute("aria-label", next);
  }
  for (const el of root.querySelectorAll("[data-i18n-placeholder]")) {
    const key = el.dataset.i18nPlaceholder;
    if (!key) continue;
    const next = language === "en" ? (I18N_EN[key] || I18N_DYNAMIC_EN[key] || key) : key;
    if (el.getAttribute("placeholder") !== next) el.setAttribute("placeholder", next);
  }
}
export let languageSelect = null;
defer(() => { languageSelect = $("language-select"); });
export const LANGUAGE_PREFERENCES = new Set(["system", "zh", "en"]);
export function normalizeLanguagePreference(value) {
  return LANGUAGE_PREFERENCES.has(value) ? value : "zh";
}
export function resolveUiLanguage(preference = localStorage.getItem("kz-language")) {
  const normalized = normalizeLanguagePreference(preference);
  if (normalized !== "system") return normalized;
  const systemLanguage = typeof navigator === "undefined" ? "" : navigator.language || "";
  return /^zh(?:[-_]|$)/i.test(systemLanguage) ? "zh" : "en";
}
export function setLanguagePreference(preference, { persist = true, rerender = true } = {}) {
  const normalized = normalizeLanguagePreference(preference);
  if (persist) localStorage.setItem("kz-language", normalized);
  languageSelect.value = normalized;
  if (rerender) {
    applyLanguage();
    syncDynamicUiLanguage();
    reconcileTasksPanel();
    syncSidebar();
    renderAgentAudit();
    if (document.querySelector("#providers-table tbody")?.children.length) renderProviders();
    $("status-tokens").title = t("点击查看上下文成分");
    if (lastWorkspaceSnapshot) renderWorkspace(lastWorkspaceSnapshot);
    if (document.body.classList.contains("documents-active")) refreshDocs();
    if (currentProject) {
      refreshWorktrees();
      refreshConversationList();
    }
    if (askActive) $("ask-title").textContent = t("权限请求");
    updateAskQueueStatus();
    // 画布上的文字(记忆图谱的边标签)不在 DOM 里,靠这个事件重画。
    document.dispatchEvent(new CustomEvent("kz:language", { detail: { language: normalized } }));
  }
}
export function syncLanguagePreferenceFromSettings(preference) {
  if (!LANGUAGE_PREFERENCES.has(preference)) return;
  setLanguagePreference(preference);
}
defer(() => {
  languageSelect.value = normalizeLanguagePreference(localStorage.getItem("kz-language"));
});
defer(() => {
  languageSelect.addEventListener("change", () => {
    setLanguagePreference(languageSelect.value);
    // UX-119:切换即存(app.json),不再等「保存」。
    persistLanguagePreference(languageSelect.value);
  });
});
defer(() => {
  applyLanguage();
});

// R-264 B10：21-palette.js 尚未迁移其提供方时，通过 globalThis 读取稳定的 i18n API。
defer(() => {
  Object.assign(globalThis, { localizeDynamic, t });
});
